CARDS=[]
def add(id,module,pre,scope,method,pitfall,mastery,difficulty,variants):
 CARDS.append(dict(id=id,module=module,pre=pre,scope=scope,method=method,pitfall=pitfall,mastery=mastery,difficulty=difficulty,variants=variants))
add('NET01','体系与物理层','层次、封装、协议与服务','OSI/TCP-IP功能、服务方向、协议三要素、设备层次和封装效率。','同层实体按协议通信，下层向相邻上层提供服务；把功能定位到层，再列封装顺序。效率=应用有效字节/全部传输字节。','协议等于服务；层数越多效率越高；网络层负责应用进程端到端可靠性；ICMP用UDP承载。','能从场景写各层协议和服务对象；高分解释每层头部开销并区分语法语义时序。','基础到常规；相邻节点与端到端服务对象是关键。',[('分层及封装辨析','.*','传输层面向端进程，链路层面向相邻节点；路由器、交换机、Hub最高工作层按题给普通设备模型判断。')])
add('NET02','体系与物理层','速率、距离、时间线','发送传播、带宽时延积、分组流水、电路报文交换和瓶颈吞吐。','发送=L/R，传播=d/v；多跳存储转发每跳须收完整分组。等速m跳n包总时长=(m+n−1)T发送+传播和，非等速用逐节点完成时间递推。','把传播速度当数据率；文件每包都加完整路径传播后简单相乘；忘首部与建路；吞吐取所有链路平均。','能画首末分组时间线并指出瓶颈；高分按异速链路递推而不套等速式。','常规到较难；异速多跳与卫星往返距离为难点。',[
('时延吞吐与多跳','.*','端到端吞吐上限受最窄链路；卫星一程含上行与下行，RTT再乘2；时间区间起止点依题。'),
('虚电路与交换方式','虚电路|电路|报文|分组','电路有建路，报文整份逐跳，分组可流水；虚电路建立路径并按标识转发，不必预留固定带宽。')])
add('NET03','体系与物理层','log2、dB、码元','奈奎斯特／香农容量、调制状态数、码元率与波形识别。','无噪声低通上限2B log2M；噪声容量B log2(1+S/N)，dB值先换10^(dB/10)。比特率=码元率×log2M；QAM状态按可组合幅相数。','把线性S/N再当dB换算；带宽Hz与速率bit/s混用；曼彻斯特规则未看题图约定。','能正反推状态数、码元率及发送时间；高分联立两容量约束并按波形判编码。','常规；两上限联立与差分编码起始跳变为综合。',[
('容量与调制','奈奎斯特|香农|QAM|ASK|FSK|相位|调制|码元|信噪比|状态数','实际率不超过适用上限；FSK改变频率，ASK幅度，PSK相位，差分方案比较相邻变化。'),
('波形编解码','曼彻斯特|NRZ|波形','曼彻斯特位中必跳变，差分曼彻斯特还看位开始是否跳变；0/1方向按题定义。')])
add('NET04','体系与物理层','接口和介质','物理接口四特性、100BaseT介质及与MAC层分工。','机械看形状引脚，电气看电平等，功能看引脚信号含义，过程看交互步骤；MAC地址属链路层。','接口引脚含义当机械形状；100BaseT误判为同轴或光纤。','能按具体描述逐项归类，不扩展到未考布线施工。','基础；概念边界明确即可。',[('物理接口与介质辨析','.*','T表示双绞线的原题语境；不从速率相同推物理介质相同。')])
add('NET05','链路层','异或、多项式、码字距离','CRC接收校验和海明距离的检纠错能力。','CRC用生成多项式做模2除，余数非0可判检测到差错，余数0仅表示未检出。编码集最小两两海明距离d决定保证检d−1位、纠floor((d−1)/2)位。','CRC余数0证明绝对无错；普通减法代异或；只求某对码字距离而非最小值。','能列模2除和全部必要距离并解释保证能力；高分区分检错与纠错。','常规；题面“未发生错误”的表述应按未检出解释并注明。',[('CRC检错','CRC|余数','保留原卷问法但解释其模型：合法码字仍可能由未检出的错误产生。'),('最小码距','海明|编码集','先求最小d再代能力公式，不能凭码长猜检纠错位数。')])
add('NET06','链路层','模序号、窗口、RTT','停等、GBN、SR确认重传、序号空间、捎带ACK与利用率。','先定ACK语义是已收最后帧还是下一个期待帧。按基序号、nextseq和已确认集合更新窗口。无差错利用率=min(1,W×T数据/(T数据+RTT+T确认))，RTT若已含某阶段不得重复加。','SR确认后任意越过未确认基帧；GBN只重传丢失帧；ACK长度忽略就把传播也删；窗口上限与当前可发量混同。','能画双向发送与ACK时间线；高分反推最小整数窗口和序号位数并验证边界。','综合到较难；捎带确认及乱序ACK会改变发送时点。',[
('确认和重传','确认|重传|GBN|SR|序号|窗口','m位序号，GBN发送最多2^m−1、接收1；等窗口SR最多2^(m−1)。GBN从最早未确认起重传，SR逐帧。'),
('利用率和位数反推','利用率|速率|长度|RTT|位数|满利用|卫星','先求满足目标利用率的ceil窗口，再按相应协议序号空间取最小m；帧长包括题定开销，分子有效数据另算。'),
('捎带与乱序ACK','捎带|乱序|基序号','捎带ACK需等待反向数据且可能占非零发送时长；SR仅连续已确认前缀使窗口基滑动。')])
add('NET07','链路层','共享介质、往返传播、内积','CSMA/CD碰撞、最短帧、退避、CDMA与信道划分。','碰撞最坏检测需往返传播及设备延迟；最短帧发送时间至少覆盖争用期。第k次退避随机槽数0…2^min(k,10)−1。CDMA按码片向量内积并归一化解码。','站间距离只除一次未扣往返Hub延迟；第11次仍用2^11；将CSMA视为绝不碰撞；CDMA等于CSMA。','能从最短帧反推距离并说明碰撞最早最晚时刻；高分处理设备延迟和正交码。','常规到综合；传播与再生延迟及退避上限为难点。',[
('碰撞与最短帧','最短|CSMA/CD|距离|争用|冲突检测|往返|传播','帧长bit/速率得到争用时间，扣往返设备延迟后再按2d/v求距离。'),
('指数退避','退避|第4次|第11次','槽长取题给争用期，最大随机槽数不是2^k而是2^k−1，k最多10。'),
('多址与复用','CDMA|FDMA|TDMA|随机接入|CA','码分、频分、时分为不同资源划分；CSMA随机争用可冲突，CA和CD处理机制不同。')])
add('NET08','链路层','帧与数据报、地址作用域','以太网封装、最小载荷、MAC服务及逐跳地址。','远端IP保留最终目标（NAT另论），二层目的MAC是本链路下一跳；跨路由重新封装。帧不足最小载荷需填充，填充不属于IP数据报长度。','用远端服务器MAC穿越路由；MAC无连接等于帧不检错；以太网原生一定有ACK。','能从十六进制帧定位首部和数据、解释每跳地址；高分分清题目另加确认机制与标准MAC服务。','常规到综合；封装边界和填充需按字节数核算。',[('MAC服务与封装','.*','以太网MAC通常无连接不可靠、不做链路ACK；原题若另外规定确认帧，则仅在其模型下计算。')])
add('NET09','链路层','源／目的MAC、拓扑','学习交换、泛洪、Hub、冲突广播域、VLAN及直通时延。','先按源MAC与入端口更新表，再查目的MAC：已知单播定向，未知／广播在允许域除入端口泛洪；Hub物理复制。VLAN划广播域边界。','从目的MAC学习；同IP子网一定二层可达；匹配目标MAC就能跨VLAN；路由器默认转广播。','能逐帧更新交换表并列实际接收者；高分在混合设备拓扑统计域数和最早转发时点。','常规到综合；多轮ARP/DNS/TCP引发的交换表演化为难点。',[
('学习泛洪和接收范围','交换|学习|转发|接收|源MAC|目的MAC|ARP|DHCP','广播在所属VLAN传播，路由接口能接到直连广播但不默认转发到其他接口。'),
('域划分与设备选择','冲突域|广播域|集线器|网桥|路由器|VLAN|子网边界|层','普通交换端口分冲突域、同VLAN仍同广播域；Hub所有端口共享冲突域。'),
('直通延迟','直通','至少读到完整目的MAC才决定转发；题给是否含前导码决定起算位置。')])
add('NET10','链路层','无线共享、帧交换时序','802.11 CSMA/CA、RTS/CTS、DIFS/SIFS、NAV和三地址。','按DIFS、退避、RTS、SIFS、CTS、SIFS、DATA、SIFS、ACK展开；题从某阶段开始计时则只保留后续。地址先区分无线直接接收／发送者与最终源目的。','收到CTS后NAV仍算已经结束的RTS/CTS；从DATA开始却再加DIFS；把AP当最终IP目的。','能画完整交换并截取所问区间；高分解释上行和下行三地址各自含义。','常规到综合；时点与地址角色必须分开。',[
('访问预约与时延','CA|RTS|CTS|NAV|DIFS|SIFS|发送数据','NAV覆盖剩余占用，SIFS短于DIFS以优先完成既有交换；ACK发送时间题说忽略才删。'),
('802.11地址','地址|上行|下行','上行常为接收AP、发送站、最终目的；下行常为目的站、发送AP、最终源；按ToDS/FromDS语境核对。')])
add('NET11','网络层','二进制掩码、前缀树','IPv4网络广播、等分/VLSM、完整划分、聚合、特殊地址和配置。','网络地址=IP按位与掩码；常规子网可用数2^主机位−2。分配按最大需求先取合适前缀，并检查已有主机、边界对齐、不重不漏。聚合取公共前缀且下一跳一致。','只看十进制连续就能聚合；忽略网络／广播／已用接口；默认网关不在直连网段；完整划分中留下地址空洞。','能给每个网段首末地址和可用范围；高分用前缀二叉树处理不等量完整划分。','常规到较难；VLSM既有地址约束与最少路由聚合为重点。',[
('掩码和地址范围','掩码|网络地址|广播|可分配|主机地址|特殊IP|环回|/20|/22|/30','非整字节掩码逐位算，不按自然类地址猜；/31等未考特殊规则不默认引入。'),
('划分和VLSM','划|均分|等分|VLSM|子网数量|完整','等分2^k份前缀增k；完整分3或5子网用树逐次二分，不必所有子网等大。'),
('聚合及配置','聚合|共同前缀|下一跳|默认网关|接口|出口|NAT','聚合不得改变去向，主机/32与默认/0保留其覆盖作用；交换转发端口无需像路由接口那样配IP。')])
add('NET12','网络层','IPv4前缀、下一跳','最长前缀匹配、直连／主机／默认路由及故障后更新。','对目的IP与每条掩码求匹配，选最长前缀；直连直接交付目标，否则交付直连可达下一跳。路由故障先重新求路径，再按新出口聚合。','先出现的匹配即选；下一跳填远端不可直达节点；聚合先做导致不同出口合并。','能填目的前缀、下一跳、接口并逐包验证；高分保留主机路由优先于更短聚合项。','常规到综合；链路失败重算和跨NAT跟踪更难。',[('路由查表和构表','.*','默认路由只在无更长匹配时使用；同网段通信不一定受错误默认网关影响，错误掩码可能改变直连判断。')])
add('NET13','网络层','IP首部、MTU、TTL','十六进制IP解析、转发首部变化、TTL、分片长度与MF。','分片可装数据=floor((MTU−首部)/8)×8（非末片），片偏移按原数据起点/8，首部每片重加；TTL每经路由转发递减，归零丢弃。','MTU直接作数据量；偏移按字节；只看片数不算末片MF；以太网交换机也减TTL。','能列每片总长、数据长、偏移、MF，并从两端TTL差数路由器。','常规到综合；对齐后比直觉多一片是关键边界。',[
('首部与TTL','TTL|首部|十六进制|封装|路由器|最短载荷','NAT会改源／目的及相关校验，普通路由至少改TTL和首部校验；初始TTL需大于经过的路由器数才能到目标。'),
('分片','分片|片数|片偏移|MF|MTU','除最后片外数据长度须8B对齐；MF看是否还有原报文后续数据，不看当前片是否装满。')])
add('NET14','网络层','广播域、IP和MAC','ARP解析、DHCP首次地址配置、ICMP封装及历史报文。','主机先判断目标是否同网段，再ARP目标或网关。首次DHCP未获可用地址时使用0.0.0.0源和有限广播目的。ICMP由IP承载。','ARP解析端到端远端MAC；首次收到Offer后Request源地址就使用待分配IP；广播跨VLAN或路由自动扩散。','能写每阶段IP和MAC及接收范围；高分说明地址池排除项和旧协议题的历史语境。','常规到综合；协议地址与广播边界联合易错。',[
('ARP及广播范围','ARP|MAC|广播|VLAN|DNS|网关','缓存空先解析本链路下一跳MAC，交换机从该帧源地址学习；不同VLAN隔离ARP。'),
('DHCP','DHCP|Discover|Request|地址池','初次Discover/Request均未正式使用被提供地址；题给服务器和静态地址从可分配池扣除。'),
('ICMP','ICMP|源抑制','按2010原题历史语境识别源抑制，不把已过时机制描述为当下推荐部署；这里保留的是历史考法。')])
add('NET15','网络层','图、距离向量、自治系统','RIP/OSPF/BGP、更新收敛、最短路、Area与AS路径。','距离向量D_x(y)=min_v(c(x,v)+D_v(y))；RIP16不可达，逐轮按题的同步时点传播。OSPF链路状态建图，BGP跨AS传播路径与策略信息。','RIP坏消息立即全网收敛；BGP直接等于全局最短路；将iBGP当OSPF；第一次交换时间零点多算一轮。','能逐轮更新表并解释所选下一跳；高分联合AS路径长度和AS内到出口代价。','综合到较难；故障传播和分层路由选择要按题的简化策略。',[
('协议类型封装和范围','RIP|OSPF|BGP|Area|封装|自治系统|内部路由','RIP/OSPF/BGP常见分别经UDP/IP/TCP；OSPF可分区域，BGP用TCP会话。'),
('距离更新与收敛','距离向量|坏消息|邻居|同步|传播|跳数增长','每轮用当轮可见邻居信息，不能提前使用尚未传播的新路径；坏消息可计数到无穷。'),
('链路状态和故障','链路状态|Dijkstra|LSI|最短路|链路失效','先更新图再计算最短路，最后按出口聚合；与DS22交叉。'),
('BGP层次选择','AS路径|eBGP|iBGP|UPDATE|出口代价','AS间eBGP、AS内iBGP；无额外策略时按原题规则比较AS路径和内部代价，不能推广成完整实际BGP决策链。')])
add('NET16','网络层','地址位数、首部与封装','IPv6地址空间、基本首部、过渡及Hop Limit。','128位相对32位地址空间扩大2^96倍而非96倍；IPv6基本首部固定40B，扩展首部另计；Hop Limit对应逐跳限制。','IPv6全部首部含扩展都固定；双栈等于把IPv4简单转成IPv6；扩大位数等于相同倍数。','能逐项解释2023题的四个判断，保留双栈和隧道的功能边界。','基础到常规；低频概念不省略。',[('IPv4/IPv6比较','.*','双栈并存两套协议，隧道在另一协议中封装；不延伸未考具体配置命令。')])
add('NET17','网络层','公网私网、端口与校验','NAT/NAPT、静态映射、重叠私网和多级转换。','每经过转换设备按方向查映射表改对应地址／端口，记录前后五元组；端口或IP参与传输校验伪首部时需重算相关校验。','NAT只改IP永远不改端口；私网直接互联网可路由；两级转换只改一次；把网络广播地址配给出口。','能逐跳列源目的IP/端口，反向还原；高分处理两边重叠私网和服务器端口映射。','常规到综合；多级映射和伪首部校验为难点。',[('映射与校验','.*','普通NAT与端口复用NAPT按题区分；UDP总长度不因只改地址端口而改变。')])
add('NET18','传输层','字节编号、RTT、连接状态','TCP双向seq/ACK、握手、累计确认、重传与释放。','每个方向独立序号；数据按字节计，SYN/FIN各占1，纯ACK不占。ACK表示下一期待字节，中间缺失不能越过累计确认。时间线分建立、数据、释放和主动端TIME_WAIT。','首次同值ACK算一次重复；被动关闭也一律等2MSL；FIN序号忘扣SYN；忽略计时终点是收到数据还是收到确认。','能补完整报文标志序号确认号和状态；高分把数据窗口限制嵌入完整RTT时间线。','常规到较难；双向序号与关闭时点联合最易差1。',[
('序号累计ACK与重传','序号|字节|确认|累计|重复ACK|重传|SYN|ACK','从每方向初始序号单独记账；三次重复ACK触发快速重传时不把最初那次算重复。'),
('连接建立和释放','握手|关闭|释放|FIN|TIME_WAIT|2MSL|建连|完整RTT|末ACK','第三次握手可承载数据须按题；主动端收到对方FIN并发ACK后计TIME_WAIT，传输时延是否忽略按原题。'),
('与UDP及首部效率比较','UDP|首部|载荷效率|请求响应','UDP无建立连接RTT，TCP初次请求通常额外1RTT；不把已有连接重新算握手。')])
add('NET19','传输层','cwnd、rwnd、已发未确认','TCP接收窗口、发送上限、在途字节和可继续发送量。','窗口上限=min(cwnd,rwnd)；可新发量=上限−仍在途未确认量，负值取0。ACK推进释放在途量，接收应用是否读取决定rwnd后续变化。','把窗口大小直接当还能发送量；接收缓存不读却每轮重置满窗口；cwnd大就不受接收方限制。','能每次ACK后列基序号、在途、两个窗口和可发量；高分处理固定rwnd限制与不断增大的cwnd。','综合；ACK增长和缓存释放两条变化链必须分开。',[('窗口和在途量','.*','2026题给8MSS的是初始阈值ssthresh，不能误读为cwnd；按题目传统慢开始初始1MSS模型，并受rwnd=2MSS限制，批次为1／2／1。')])
add('NET20','传输层','TCP ACK、阈值、MSS','慢开始、拥塞避免、超时、快速重传及应用传输RTT。','按题给初始cwnd和ssthresh开始逐ACK更新，慢开始通常每确认一个新段增加1MSS，拥塞避免约每RTT增加1MSS。超时按题模型重设阈值和窗口，再与rwnd取最小。','任何初态都从1MSS开始；忽略按每ACK而非粗略轮倍增；超时和重复ACK机制混用；用cwnd替实际发送窗口。','能列每ACK的窗口并按阈值切换；高分将握手、HTML依赖和接收缓存约束一起计时。','综合到较难；分段ACK与阈值切换及应用依赖为重点。',[
('窗口增长与超时','.*','历史题采用其明确的TCP简化模型；阈值减半的基准按题给丢失时窗口，不从当前接收窗口擅推。'),
('应用与完整时间线','HTTP|连接|FTP|平均应用|完整RTT|全程|末ACK','应用对象有先后依赖，开始收到ACK才能发受窗口限制的下一批；计应用平均速率时分子只用应用数据。')])
add('NET21','传输层','端口、反码加法','UDP服务、复用分用、校验和、首部效率及TCP对比。','UDP按目的端口交付应用，不保证到达／顺序；反码校验将16位字相加，最高进位回卷再相加，最后取反；伪首部只参与校验不作为UDP实际首部发送。','检错等于可靠；回卷进位漏加；端口属于主机IP层；修改IP不影响UDP校验。','能算末步校验并定位应用端口；高分追踪NAPT导致的校验变化和请求往返。','常规到综合；反码与伪首部是难点。',[('UDP性质和端口','UDP|端口|复用|分用|TCP|首部|载荷|RTT|POP3','标准UDP首部8B，TCP无选项20B；应用协议实际承载以原卷模型为准。'),('反码校验','校验|伪首部','一补和每次溢出的高位回卷低位，再取反；IP或端口变化可能要求重算。')])
add('NET22','应用层','域名层次、缓存、递归迭代','DNS请求次数和网页前解析时间。','先定缓存位置，再区分递归由被请求者继续查、迭代返回下一服务器线索。分别统计主机发出的请求和本地服务器发出的请求。','把所有DNS报文算成主机发出；根服务器直接给所有最终地址；已有缓存仍走全层次。','能画查询链并按各段RTT计算最短最长；高分与TCP握手HTTP依赖串接。','常规到综合；统计主体和缓存假设决定答案。',[('查询路径与计数','.*','原题传统DNS通常用UDP，不能推广为永不使用TCP；只在题给通信栈范围内解释。')])
add('NET23','应用层','TCP连接、请求对象依赖','HTTP首部、持久／非持久、并行／流水、Cookie与访问时间。','先取HTML，再知道引用对象；非持久且不并行通常每对象建连和请求各1RTT，持续非流水复用连接但请求逐个等响应；若有拥塞窗口再受分批发送限制。','HTML漏计为对象；持久等于流水；Cookie等于缓存；已有连接重复握手；未给并行却同时取图。','能逐阶段计DNS、握手和每对象请求；高分给慢开始下最短可行时间线。','常规到较难；应用依赖与传输窗口交叉不能简单数对象。',[
('访问流程及计时','HTTP|网页|Web|请求|对象|图像|DNS|端口映射|访问时间','按题给HTTP版本和连接选项，不默认现代浏览器优化；网络映射只作为传输前提。'),
('Cookie与首部语义','Cookie|Host|Close|请求行|购物车','Cookie支持跨请求状态关联，Host标识虚拟主机，Connection:Close表达关闭意图；缓存加速与Cookie功能不同。')])
add('NET24','应用层','TCP连接和端口','FTP控制／数据连接、主动模式端口与生命周期。','登录建立控制连接，文件传输另建数据连接；控制常持续，数据按传输任务建立关闭。主动模式服务器数据端口通常20，控制21。','FTP只有一条TCP；任何数据连接都固定服务器20忽略模式；数据连接关闭等于登录控制连接也关。','能分别画两连接及其用途；高分在题指定数据连接上计传输和ACK时间。','基础到综合；与TCP时序交叉时复杂度提高。',[('双连接与数据传输','.*','端口20的结论限主动模式；原题未要求的被动配置不展开，不能用其推翻题设模式。')])
add('NET25','应用层','邮件用户代理和服务器','SMTP发件中继、POP3收件、连接及编码。','用户提交和邮件服务器间转发用SMTP，用户取信可用POP3；按发送／中继／读取三个动作定位协议。原始SMTP内容为7位ASCII，二进制内容需编码。','POP3承担发件中继；同一POP3连接只能取一封；原始SMTP直接原样传任意二进制。','能画完整发件到收件路径并标协议；不扩展未考服务器配置。','基础到常规；服务方向和编码前提需保留。',[('协议分工与编码','.*','传统真题SMTP/POP3均基于TCP，可靠传输来自传输层服务而非把UDP检错等同可靠。')])
add('NET26','应用层','客户与服务角色','C/S和P2P角色、直接通信及分发特点。','按某次交互角色判断请求者与服务者；P2P节点可同时提供和请求资源，节点间可直接交换。','P2P完全没有任何服务器；C/S客户端之间必直接通信；把角色永久绑定一台机器。','能解释题目中的角色与分发路径，避免产品层面的扩张。','基础；低频概念保留而不据频次删去。',[('服务角色与分发','.*','架构描述逻辑角色，不等于每台物理机只有一种永久身份。')])
add('NET27','链路层','比特串、帧定界','HDLC零比特填充和去填充。','发送数据部分每连续五个1后插入0，插入的0使计数重置；接收在相同规则下删除填充0。','把第六个1才触发；把帧定界标志也按数据填充；漏跨字节的连续1。','能逐位标出新增位置并逆向还原原串。','常规；只有一次的考法也保留完整操作规则。',[('五个1后插0','.*','连续计数跨字节，不因视觉分组重置；定界标志不是被填充数据。')])
add('NET28','体系与物理层','控制平面、数据平面','SDN控制器下发流表的接口方向。','应用与控制器之间为北向，控制器与转发设备之间为南向；控制器制定规则，交换机按流表转发。','南北按地理位置；流表下发属应用直接逐包转发；将东西向接口套到交换机控制。','能定位2022题的控制器→交换机流表消息，不扩张具体协议配置。','基础；低频接口方向辨析。',[('控制器与流表','.*','用通信两端角色确定南向，不靠箭头画在图的上下判断。')])
